func:
flow.set('qybm', '012345678912');
flow.set('wgbm', '01234567891201');
flow.set('secretKey', 'ab23dcef');
flow.set('baseUrl', 'http://127.0.0.1:5903/rabbitmqfcsb');
flow.set('videoCode', '01234567891234567890');
flow.set('rtsCount', 0);
flow.set('eventCount', 0);
flow.set('videoCount', 0);
node.status({fill:'green', shape:'dot', text:'qybm=012345678912 mock=:5903'});
return null;

const qybm = flow.get('qybm') || '012345678912';
const now = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T',' ').slice(0,19);
const count = (flow.get('rtsCount') || 0) + 1;
flow.set('rtsCount', count);
const base = [
  ['0123456789120101001', 24 + Math.sin(count / 3) * 3 + Math.random()],
  ['0123456789120102001', 45 + Math.cos(count / 4) * 5 + Math.random() * 2],
  ['0123456789120103001', 0.8 + Math.sin(count / 5) * 0.15],
  ['0123456789120104001', 12 + Math.random() * 3],
  ['0123456789120105001', 0],
  ['0123456789120106001', count % 9 === 0 ? 1 : 0]
];
msg.payload = {
  qybm,
  data: {
    rts: base.map(([tnm, val]) => ({tnm, ts: now, val: Number(val).toFixed(2)}))
  }
};
msg.dustEndpoint = 'rtsData';
msg.dustOuter = { qybm, wgbm: flow.get('wgbm') || (qybm + '01') };
node.status({fill:'blue', shape:'dot', text:`rts ${msg.payload.data.rts.length}点 ${now.slice(11)}`});
return msg;

const qybm = flow.get('qybm') || '012345678912';
const now = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T',' ').slice(0,19);
const scd = Number(msg.payload);
const isClear = scd === 0;
const avx = isClear ? 38.2 : 126.8;
const event = {
  ts: now,
  oname: '0123456789120106001',
  avx: avx.toFixed(4),
  scd,
  threshold: isClear ? 0 : 100.0,
  content: isClear ? '粉尘浓度恢复正常，自动消警' : '粉尘浓度超上上限报警，请立即联锁除尘并检查清扫'
};
msg.payload = { qybm, data: { events: [event] } };
msg.dustEndpoint = 'eventsData';
msg.dustOuter = { qybm };
flow.set('eventCount', (flow.get('eventCount') || 0) + 1);
node.status({fill:isClear?'green':'red', shape:'dot', text:isClear?'消警':'报警 scd=4'});
return msg;

const qybm = flow.get('qybm') || '012345678912';
const now = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T',' ').slice(0,19);
const img = msg.imgBase64 || 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAFgwJ/l0X9WQAAAABJRU5ErkJggg==';
msg.payload = {
  qybm,
  data: {
    ts: now,
    videoCode: flow.get('videoCode') || '01234567891234567890',
    alarmType: msg.alarmType || 'SJ02001',
    content: msg.content || '视频AI识别到粉尘区域疑似烟火事件'
  }
};
msg.dustEndpoint = 'videosData';
msg.dustOuter = { qybm, img };
flow.set('videoCount', (flow.get('videoCount') || 0) + 1);
node.status({fill:'yellow', shape:'dot', text:'video img=' + Math.round(img.length / 1024) + 'KB'});
return msg;

if (!Buffer.isBuffer(msg.payload)) {
  msg.payload = Buffer.from(msg.payload);
}
if (msg.payload.length > 500 * 1024) {
  node.error('图片超过文档限制 500KB: ' + msg.payload.length + ' bytes', msg);
  return null;
}
msg.imgBase64 = msg.payload.toString('base64');
node.status({fill:'green', shape:'dot', text: msg.filename + ' ' + Math.round(msg.payload.length / 1024) + 'KB'});
return msg;

const key = flow.get('secretKey') || 'ab23dcef';
const iv = '12345678';
const baseUrl = flow.get('baseUrl') || 'http://127.0.0.1:5901/rabbitmqfcsb';
if (!CryptoJS) {
  node.error('crypto-js 未加载，请确认 Node-RED 已启用 functionExternalModules 并安装 crypto-js', msg);
  return null;
}
const plain = JSON.stringify(msg.payload);
const encrypted = CryptoJS.DES.encrypt(
  CryptoJS.enc.Utf8.parse(plain),
  CryptoJS.enc.Utf8.parse(key),
  { iv: CryptoJS.enc.Utf8.parse(iv), mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7 }
);
const base64Text = encrypted.ciphertext.toString(CryptoJS.enc.Base64);
const hex = CryptoJS.enc.Utf8.parse(base64Text).toString(CryptoJS.enc.Hex).toUpperCase();
const outer = Object.assign({}, msg.dustOuter || {}, { data: hex });
msg.payload = outer;
msg.headers = {'Content-Type': 'application/json'};
msg.method = 'POST';
msg.url = `${baseUrl}/api/${msg.dustEndpoint}`;
msg._plain = plain;
msg._encryptedPreview = hex.slice(0, 96);
node.status({fill:'green', shape:'dot', text:`${msg.dustEndpoint} encrypted ${hex.length}`});
return msg;

const p = msg.payload || {};
const ok = p.code === 200;
node.status({fill: ok ? 'green' : 'red', shape:'dot', text: ok ? '操作成功' : JSON.stringify(p).slice(0,40)});
return msg;

msg.payload = {
  qybm: flow.get('qybm'),
  wgbm: flow.get('wgbm'),
  baseUrl: flow.get('baseUrl'),
  counters: {
    rts: flow.get('rtsCount') || 0,
    events: flow.get('eventCount') || 0,
    videos: flow.get('videoCount') || 0
  },
  endpoints: ['/api/rtsData','/api/eventsData','/api/videosData']
};
return msg;

const event = msg.payload && msg.payload.data && msg.payload.data.events && msg.payload.data.events[0];
if (!event) return null;
if (Number(event.scd) <= 0) {
  node.status({fill:'blue', shape:'ring', text:'消警不朗读'});
  return null;
}
const text = event.content || '粉尘涉爆监测发生报警';
msg.payload = '粉尘涉爆报警，' + text;
node.status({fill:'red', shape:'dot', text: msg.payload.slice(0, 24)});
return msg;

const event = msg.payload && msg.payload.data && msg.payload.data.events && msg.payload.data.events[0];
if (!event || Number(event.scd) <= 0) {
  node.status({fill:'grey', shape:'ring', text:'非报警不抓拍'});
  return null;
}
msg.payload = '';
msg.alarmType = 'SJ02001';
msg.content = '传感器报警联动海康抓拍：' + (event.content || '现场报警');
msg.eventTs = event.ts;
node.status({fill:'yellow', shape:'dot', text:'触发海康抓拍'});
return msg;

if (!Buffer.isBuffer(msg.payload)) {
  msg.payload = Buffer.from(msg.payload, 'binary');
}
if (msg.payload.length === 0) {
  node.error('海康抓拍返回空图片', msg);
  return null;
}
if (msg.payload.length > 500 * 1024) {
  node.error('海康抓拍图片超过文档限制 500KB: ' + msg.payload.length + ' bytes', msg);
  return null;
}
msg.imgBase64 = msg.payload.toString('base64');
msg.alarmType = msg.alarmType || 'SJ02001';
msg.content = msg.content || '海康摄像头报警抓拍上传';
node.status({fill:'green', shape:'dot', text:'JPEG ' + Math.round(msg.payload.length / 1024) + 'KB'});
return msg;
